#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Never trace commands which handle copied credentials, even under bash -x.
set +x

setup_backend() { node --import tsx scripts/local-setup.ts "$@"; }
save_value() { printf '%s' "$2" | setup_backend set "$1"; }
pending() { say "$1"; say "Saved configuration is retained. Rerun bash scripts/setup-local.sh to resume."; exit 1; }

run_wizard() {
  if [[ "${1:-}" == "--help" ]]; then
    printf '%s\n' 'Usage: bash scripts/setup-local.sh' \
      'Interactive first run for a local production control plane, private .env.live, ngrok,' \
      'GitHub App creation/selected-repository installation, and E2B template setup.' \
      'Requires Node 24, Git and npm. Account actions require your browser approval.' \
      'Rerun to resume; existing credentials are retained. --help needs no terminal.'
    return 0
  fi
  if (( $# )); then printf '%s\n' 'Unknown argument. Use --help.' >&2; exit 1; fi
  if [[ ! -t 0 || ! -t 1 ]]; then printf '%s\n' 'Run this wizard yourself in an interactive terminal. Use --help for details.' >&2; exit 1; fi
  cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.."
  # Library prompts must not inspect another dotenv file or execute its contents.
  ENV_FILE=/dev/null
  TOTAL_STAGES=8
  trap 'printf "\nSetup interrupted; existing private configuration is retained. Rerun to resume.\n" >&2; exit 130' INT
  trap 'printf "\nSetup stopped; existing private configuration is retained. Rerun to resume.\n" >&2; exit 143' TERM

  banner "Ephemeral local live setup"

  stage "Prerequisites"
  say "Use Node 24, Git and npm. This setup runs the control plane on this computer."
  if ! command -v node >/dev/null 2>&1 || [[ "$(node -p 'process.versions.node.split(".")[0]' 2>/dev/null)" != 24 ]]; then
    open_url "https://nodejs.org/en/download"
    pending "Install Node 24, then reopen your terminal and rerun this wizard."
  fi
  if ! command -v git >/dev/null 2>&1 || ! command -v npm >/dev/null 2>&1; then pending "Install Git and npm, then rerun."; fi
  if [[ ! -f node_modules/tsx/package.json ]]; then
    say "Installing this checkout's pinned npm dependencies."
    npm ci || pending "Dependency installation failed. Resolve it and rerun."
  fi

  stage "Private local configuration and port"
  setup_backend init
  PORT=$(setup_backend get PORT)
  say "The default loopback port is 4311. Keep the selected port stable while sessions run."
  say "Current selected port: $PORT"
  ask SELECTED_PORT "Loopback port [Enter keeps current]:"
  if [[ -n "$SELECTED_PORT" && "$SELECTED_PORT" != "$PORT" ]]; then
    save_value PORT "$SELECTED_PORT" || pending "Port update failed; review existing configuration."
    PORT=$(setup_backend get PORT)
  fi
  note "Configuration stays in ignored .env.live; private state stays in .data/local-live."

  stage "ngrok account and tunnel"
  open_url "https://dashboard.ngrok.com/get-started/setup"
  step "Sign in or create your ngrok account, then follow its agent installation instructions."
  step "Configure the account authtoken privately in the agent configuration editor."
  say "Never paste the authtoken into a shell argument, chat, logs or this wizard."
  say "Start this command in a SECOND terminal and keep it running:"
  say "ngrok http http://127.0.0.1:$PORT --inspect=false --log=false"
  note "Do not enable request inspection, payload logging or an extra gateway login gate."
  pause "Press Enter once ngrok is running and shows a public HTTPS URL."

  stage "Public HTTPS origin"
  if setup_backend has PUBLIC_URL; then
    PUBLIC_URL=$(setup_backend get PUBLIC_URL)
    say "Retaining configured origin: $PUBLIC_URL"
    note "Use this same ngrok domain. A changed domain requires session reconciliation and"
    note "an explicit private config update plus GitHub App callback update together."
    confirm "Does your running tunnel use this exact origin?" || pending "Origin reconciliation is pending; setup will not replace PUBLIC_URL."
  else
    ask PUBLIC_URL "Paste the assigned HTTPS origin (no path/query):"
    save_value PUBLIC_URL "$PUBLIC_URL" || pending "Origin could not be saved. Use a public HTTPS origin with no path/query."
  fi

  stage "GitHub identity, App and selected repository"
  say "Use a dedicated disposable repository that you already own."
  say "The next step looks up your numeric ID and opens GitHub for your review."
  say "You approve App creation and selected-repository installation in your browser."
  setup_backend github || pending "GitHub setup is pending; existing credentials were retained."

  stage "E2B account and API key"
  if setup_backend has E2B_API_KEY; then
    say "An E2B API key is already saved; retaining it without displaying it."
  else
    open_url "https://console.e2b.dev"
    step "Sign in or create your E2B account. Open its API keys area and copy your key."
    note "Check account credits and provider billing. E2B usage can consume resources."
    ask_secret E2B_API_KEY "Paste the E2B API key (hidden):"
    save_value E2B_API_KEY "$E2B_API_KEY" || pending "API key was not saved; rerun this stage."
    unset E2B_API_KEY
  fi

  stage "Reuse or build the custom E2B template"
  if setup_backend has E2B_TEMPLATE_ID; then
    say "A template ID is already saved; retaining it. Doctor will verify readiness."
  else
    say "Reuse a compatible template built from this checkout's pinned recipe, or build one."
    ask E2B_TEMPLATE_ID "Existing template ID or alias [Enter to consider a new build]:"
    if [[ -n "$E2B_TEMPLATE_ID" ]]; then
      save_value E2B_TEMPLATE_ID "$E2B_TEMPLATE_ID" || pending "Template ID was not saved."
    else
      warn "Building alias ephemeral-codex consumes E2B resources, may incur charges and update its default tag."
      say "If that alias is already in use, prefer reusing its compatible template ID."
      confirm "Build this checkout's custom E2B template now?" || pending "Template setup is pending. Rerun and supply a template ID or approve a build."
      setup_backend template-build --confirm-build || pending "Template build did not complete. Inspect private build recovery state before retrying."
    fi
  fi

  stage "Build, validate and launch handoff"
  say "Building production browser assets."
  npm run build || pending "Production build failed. Resolve the build and rerun."
  setup_backend doctor || pending "Validation is pending. Resolve the reported prerequisite or provider checks, then rerun."
  say "Preparation passed. No sandbox or live acceptance test was performed."
  say "Keep ngrok running. Start the production server in this terminal with:"
  say "npm run live"
  say "After the server starts, optionally run npm run setup:local -- tunnel-check in another terminal."
  say "Open $PUBLIC_URL in your browser, sign in, and follow docs/LOCAL-LIVE.md."
  say "Fresh Codex device authentication is required inside each eventual VM."
  say "Stop any machines and resolve cleanup before stopping the server or tunnel."
  finish
}

run_wizard "$@"; exit
